package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated retirement date. {@code date} is null when it was left blank: the sheet's today. */
public record RetireFrom(LocalDate date) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRetire {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // A blank date takes the sheet's today (filled in when stored).
    public void validate(@RequestBody RetireRequest body, Out<RetireFrom> from) throws InvalidPersonException {
        String raw = body == null || body.from() == null ? "" : body.from().trim();
        if (raw.isEmpty()) {
            from.set(new RetireFrom(null));
            return;
        }
        try {
            from.set(new RetireFrom(LocalDate.parse(raw, ISO)));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class RetirePerson {
    // Person is a record, so the retired person is published as the response in place of the loaded one.
    public void retire(@Val RetireFrom from, @Val Person person, People people, Sheets sheets,
            Out<PersonResponse> responseOut) {
        Person retired = new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                from.date() != null ? from.date() : sheets.today(person.sheetId()), person.holds(), person.dated(), person.terms(), person.contact(), person.aliases(), person.origin());
        people.retire(retired.id(), retired.retiredFrom());
        responseOut.set(PersonResponse.from(retired, sheets.today(person.sheetId())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditPersonRetired {
    public void audit(@Val Person loaded, @Val PersonResponse retired, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line("PERSON_RETIRED", loaded.sheetId(), Audit.user(connection), "name=" + retired.name(),
                "from=" + retired.retiredFrom()));
    }
}
package net.officefloor.hq.app.person;

/** The body of a retirement: the date retired from, yyyy-mm-dd, blank for the sheet's today. */
public record RetireRequest(String from) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;

public class RefuseRetiredInput {
    // The date a claim is being added to (a blank date is the entry date, else the sheet's today) must not be after its person's retirement.
    public void refuse(@Val ClaimInput input, @Val Person person, Settings settings) throws ClaimAfterRetirementException {
        check(person, input.date() != null ? input.date() : settings.entryDate(person.sheetId()));
    }

    static void check(Person person, LocalDate date) throws ClaimAfterRetirementException {
        if (person != null && person.retired() && date.isAfter(person.retiredFrom())) {
            throw new ClaimAfterRetirementException(person.name() + " is retired from " + person.retiredFrom()
                    + ": no claim dated " + date + " can be added or edited.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class RefuseRetiredClaim {
    // The date a claim is being edited to (a blank date is the sheet's today) must not be after its person's retirement.
    public void refuse(@Val ClaimInput input, @Val Claim claim, People people, Sheets sheets)
            throws ClaimAfterRetirementException {
        RefuseRetiredInput.check(people.find(claim.sheetId(), claim.personId()),
                input.date() != null ? input.date() : sheets.today(claim.sheetId()));
    }
}
package net.officefloor.hq.app.claim;

/** A claim cannot be added or edited to a date after its person's retirement date. */
public class ClaimAfterRetirementException extends Exception {

    public ClaimAfterRetirementException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimAfterRetirement {
    public void handle(@Parameter ClaimAfterRetirementException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
    }
}
-- The date a person is retired from (null when not retired). A person with one set counts as retired
-- at once, whatever the date; claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Whether the person is retired, the date they are retired from, and the control that retires them
 * from a date (a blank date is the sheet's today). A person with a date set is retired at once.
 */
function PersonRetire({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [date, setDate] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const retire = useMutation({
    mutationFn: (from: string) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, { from }, user),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The person could not be retired.'),
  });

  return (
    <td>
      <span data-testid="person-retired">{person?.retiredFrom ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person?.retiredFrom ?? ''}</span>{' '}
      <input
        data-testid="person-retire-date"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-retire"
        disabled={retire.isPending}
        onClick={() => {
          setError('');
          const d = date.trim();
          if (d !== '' && !DATE.test(d)) {
            setError('The date must be yyyy-mm-dd.');
            return;
          }
          once(() => retire.mutateAsync(d));
        }}
      >
        Retire
      </button>
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 18, Component: () => <th>Retired</th> }),
  PersonCells.fill({ order: 18, Component: PersonRetire }),
];

