import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total. `terms` are their own terms in days, which come before those of their grade
 * and of the sheet; null for none. `contact` is their contact, trimmed and lower-cased, unique on the sheet; null
 * for none. `aliases` are their aliases, sorted as names are compared (ignoring case); the quick-add bar and the
 * paste box find a person by one as well as by the name. A name or alias is unique across the sheet's tree (its
 * ancestors and descendants); `clashing` is whether the person's name or an alias is used by someone else there all
 * the same (they were on the sheet before), which refuses every edit of them until a rename frees them. `origin` is
 * the id of the sheet they were transferred from; null when they were not transferred in.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[]; terms: number | null; contact: string | null; aliases: string[]; clashing: boolean; origin: string | null };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };
    private int sheetColumn;
    private int personColumn;

    @Override
    public void init(Connection conn, String schemaName, String triggerName, String tableName, boolean before, int type)
            throws SQLException {
        columns = new ArrayList<>();
        try (ResultSet rs = conn.getMetaData().getColumns(null, schemaName, tableName, null)) {
            while (rs.next()) {
                columns.add(rs.getString("COLUMN_NAME"));
            }
        }
        // The sheet's own row names its sheet by its id.
        sheetColumn = columns.indexOf("SHEET".equals(tableName) ? "ID" : "SHEET_ID");
        personColumn = columns.indexOf("PERSON_ID");
        insert = "INSERT INTO " + tableName + "_HISTORY (" + String.join(", ", columns)
                + ", HISTORY_ON, HISTORY_GONE) VALUES (" + "?, ".repeat(columns.size()) + "?, ?)";
    }

    @Override
    public void fire(Connection conn, Object[] oldRow, Object[] newRow) throws SQLException {
        Object[] row = newRow != null ? newRow : oldRow;
        try (PreparedStatement ps = conn.prepareStatement(insert)) {
            for (int i = 0; i < columns.size(); i++) {
                ps.setObject(i + 1, row[i]);
            }
            ps.setObject(columns.size() + 1, today(conn, sheetOf(conn, row)));
            ps.setBoolean(columns.size() + 2, newRow == null);
            ps.executeUpdate();
        }
    }

    /** The row's sheet: its own, else its person's. */
    private String sheetOf(Connection conn, Object[] row) throws SQLException {
        if (sheetColumn >= 0) {
            return (String) row[sheetColumn];
        }
        try (PreparedStatement ps = conn.prepareStatement("SELECT sheet_id FROM person WHERE id = ?")) {
            ps.setObject(1, row[personColumn]);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getString(1) : null;

